const std = @import("std");
const linux = std.os.linux;
const raw = @import("raw");

comptime {
    if (!std.mem.eql(u8, @import("builtin").zig_version_string, "0.17.0")) @compileError("Requires exact Zig 0.17.0");
}

const Pipe = struct {
    fds: [2]linux.fd_t,
    fn init() !Pipe {
        var fds: [2]linux.fd_t = undefined;
        if (linux.errno(linux.pipe2(&fds, .{ .NONBLOCK = true, .CLOEXEC = true })) != .SUCCESS) return error.PrivatePipeFailed;
        return .{ .fds = fds };
    }
    fn deinit(self: *Pipe) void {
        for (self.fds) |fd| {
            if (fd >= 0) _ = linux.close(fd);
        }
    }
    fn put(self: *Pipe, byte: u8) !void {
        const bytes = [_]u8{byte};
        if (linux.write(self.fds[1], &bytes, 1) != 1) return error.PrivateWriteFailed;
    }
    fn take(self: *Pipe) !?u8 {
        var bytes = [_]u8{165};
        const result = linux.read(self.fds[0], &bytes, 1);
        if (result == 1) return bytes[0];
        if (linux.errno(result) == .AGAIN and bytes[0] == 165) return null;
        return error.PrivateReadUnexpected;
    }
    fn readable(self: *Pipe) !bool {
        var fds = [_]linux.pollfd{.{ .fd = self.fds[0], .events = linux.POLL.IN, .revents = 0 }};
        const result = linux.poll(&fds, 1, 0);
        if (result == 0 and fds[0].revents == 0) return false;
        if (result == 1 and fds[0].revents == linux.POLL.IN) return true;
        return error.PrivatePollUnexpected;
    }
};

const Stage = struct {
    buffer: [2]u8 = .{ 165, 165 },
    b_readable: ?bool = null,
    witness: ?u8 = null,
};
const Row = struct {
    kind: enum { drain, link, boundary },
    mode: enum { blocked_prior, blocked_drain, short, timeout, invalid_fd, invalid_opcode, split },
    request_flags: u8,
    prepared_flags: [3]?u8 = .{ null, null, null },
    submitted: [2]?u32 = .{ null, null },
    early: [3]bool = .{ false, false, false },
    completions: [3]?linux.io_uring_cqe = .{ null, null, null },
    before: Stage = .{},
    after: Stage = .{},
    guards: u32 = 0,
};

fn completion(ring: *linux.IoUring, row: *Row, early: bool) !u64 {
    const timeout: linux.kernel_timespec = .{ .sec = 1, .nsec = 0 };
    try raw.wait_with_timeout(ring, 1, &timeout, null);
    const cqe = try ring.copy_cqe();
    if (cqe.user_data < 1 or cqe.user_data > 3 or cqe.flags != 0) return error.UnexpectedCqe;
    const index: usize = @intCast(cqe.user_data - 1);
    if (row.completions[index] != null) return error.DuplicateCqe;
    row.completions[index] = cqe;
    row.early[index] = early;
    return cqe.user_data;
}

fn guard(ring: *linux.IoUring, row: *Row) !void {
    const timeout: linux.kernel_timespec = .{ .sec = 0, .nsec = 1_000_000 };
    raw.wait_with_timeout(ring, 1, &timeout, null) catch |err| {
        if (err == error.WaitTimedOut and ring.cq_ready() == 0) {
            row.guards += 1;
            return;
        }
        return err;
    };
    return error.UnexpectedEarlyCompletion;
}

fn drained(ring: *linux.IoUring) !void {
    if (ring.sq_ready() != 0 or ring.cq_ready() != 0) return error.QueueNotDrained;
}

fn drain(flags: u8, prior_ready: bool) !Row {
    var a = try Pipe.init();
    defer a.deinit();
    var b = try Pipe.init();
    defer b.deinit();
    var witness = try Pipe.init();
    defer witness.deinit();
    var ring = try linux.IoUring.init(8, 0);
    defer ring.deinit();
    var bytes = [_]u8{ 165, 165 };
    const write_bytes = [_]u8{99};
    var row: Row = .{ .kind = .drain, .mode = if (prior_ready) .blocked_drain else .blocked_prior, .request_flags = flags };
    if (prior_ready) try a.put(97) else try b.put(98);
    const first = try ring.read(1, a.fds[0], .{ .buffer = bytes[0..1] }, std.math.maxInt(u64));
    const middle = try ring.read(2, b.fds[0], .{ .buffer = bytes[1..2] }, std.math.maxInt(u64));
    middle.flags = flags;
    const last = try ring.write(3, witness.fds[1], &write_bytes, std.math.maxInt(u64));
    row.prepared_flags = .{ first.flags, middle.flags, last.flags };
    row.submitted[0] = try ring.submit();
    if (row.submitted[0] != 3 or ring.sq_ready() != 0) return error.SubmissionNotConsumed;
    if (flags == 0) {
        _ = try completion(&ring, &row, true);
        _ = try completion(&ring, &row, true);
    } else if (prior_ready) {
        if (try completion(&ring, &row, true) != 1) return error.DrainFirstWrong;
    }
    try guard(&ring, &row);
    try guard(&ring, &row);
    row.before = .{ .buffer = bytes, .b_readable = try b.readable(), .witness = try witness.take() };
    if (flags != 0 and row.before.witness != null) return error.DrainWitnessStarted;
    if (prior_ready) try b.put(98) else try a.put(97);
    while (row.completions[0] == null or row.completions[1] == null or row.completions[2] == null) {
        _ = try completion(&ring, &row, false);
    }
    for (row.completions) |cqe| if (cqe == null or cqe.?.res != 1) return error.DrainResultWrong;
    row.after = .{ .buffer = bytes, .b_readable = try b.readable(), .witness = try witness.take() };
    try drained(&ring);
    return row;
}

fn linked(flags: u8, mode: @FieldType(Row, "mode")) !Row {
    var source = try Pipe.init();
    defer source.deinit();
    var witness = try Pipe.init();
    defer witness.deinit();
    var ring = try linux.IoUring.init(8, 0);
    defer ring.deinit();
    var bytes = [_]u8{ 165, 165 };
    const write_bytes = [_]u8{99};
    const timeout: linux.kernel_timespec = .{ .sec = 0, .nsec = 1_000_000 };
    var row: Row = .{ .kind = .link, .mode = mode, .request_flags = flags };
    if (mode == .short) {
        try source.put(97);
        if (linux.errno(linux.close(source.fds[1])) != .SUCCESS) return error.SourceWriterCloseFailed;
        source.fds[1] = -1;
    }
    const first = if (mode == .timeout) try ring.timeout(1, &timeout, 0, 0) else try ring.read(1, if (mode == .invalid_fd) -1 else source.fds[0], .{ .buffer = &bytes }, std.math.maxInt(u64));
    if (mode == .invalid_opcode) first.opcode = @fromBackingInt(@intCast(255));
    first.flags = flags;
    const last = try ring.write(2, witness.fds[1], &write_bytes, std.math.maxInt(u64));
    row.prepared_flags = .{ first.flags, last.flags, null };
    row.submitted[0] = try ring.submit();
    if (mode == .invalid_opcode and row.submitted[0] == 1 and ring.sq_ready() == 1) {
        row.submitted[1] = try ring.submit();
        if (row.submitted[1] != 1) return error.PartialSubmissionWrong;
    } else if (row.submitted[0] != 2) return error.SubmissionWrong;
    _ = try completion(&ring, &row, false);
    _ = try completion(&ring, &row, false);
    row.after = .{ .buffer = bytes, .witness = try witness.take() };
    try drained(&ring);
    return row;
}

fn boundary(flags: u8) !Row {
    var source = try Pipe.init();
    defer source.deinit();
    if (linux.fcntl(source.fds[0], linux.F.SETFL, 0) != 0) return error.BlockingSourceFailed;
    var witness = try Pipe.init();
    defer witness.deinit();
    var ring = try linux.IoUring.init(8, 0);
    defer ring.deinit();
    var bytes = [_]u8{ 165, 165 };
    const write_bytes = [_]u8{99};
    var row: Row = .{ .kind = .boundary, .mode = .split, .request_flags = flags };
    const first = try ring.read(1, source.fds[0], .{ .buffer = bytes[0..1] }, std.math.maxInt(u64));
    first.flags = flags;
    row.prepared_flags[0] = first.flags;
    row.submitted[0] = try ring.submit();
    if (row.submitted[0] != 1 or ring.sq_ready() != 0) return error.FirstSubmissionWrong;
    const last = try ring.write(2, witness.fds[1], &write_bytes, std.math.maxInt(u64));
    row.prepared_flags[1] = last.flags;
    row.submitted[1] = try ring.submit();
    if (row.submitted[1] != 1) return error.SecondSubmissionWrong;
    if (try completion(&ring, &row, true) != 2) return error.CrossSubmissionLinked;
    guard(&ring, &row) catch |err| {
        if (ring.cq_ready() != 0) {
            const unexpected = try ring.copy_cqe();
            std.debug.print("{{\"event\":\"unexpected_boundary_cqe\",\"request_flags\":{d},\"tag\":{d},\"result\":{d},\"cqe_flags\":{d}}}\n", .{ flags, unexpected.user_data, unexpected.res, unexpected.flags });
        }
        return err;
    };
    row.before = .{ .buffer = bytes, .witness = try witness.take() };
    if (row.before.witness != 99 or bytes[0] != 165) return error.SplitWitnessWrong;
    try source.put(97);
    if (try completion(&ring, &row, false) != 1) return error.SplitReadWrong;
    row.after = .{ .buffer = bytes, .witness = try witness.take() };
    try drained(&ring);
    return row;
}

pub fn main(init: std.process.Init) !void {
    var rows: [19]Row = undefined;
    var used: usize = 0;
    for ([_]u8{ 0, linux.IOSQE_IO_DRAIN }) |flag| for ([_]bool{ false, true }) |ready| {
        rows[used] = try drain(flag, ready);
        used += 1;
    };
    for ([_]u8{ 0, linux.IOSQE_IO_LINK, linux.IOSQE_IO_HARDLINK }) |flag| for ([_]@FieldType(Row, "mode"){ .short, .timeout, .invalid_fd }) |mode| {
        rows[used] = try linked(flag, mode);
        used += 1;
    };
    for ([_]u8{ 0, linux.IOSQE_IO_LINK, linux.IOSQE_IO_HARDLINK }) |flag| {
        rows[used] = try linked(flag, .invalid_opcode);
        used += 1;
    }
    for ([_]u8{ 0, linux.IOSQE_IO_LINK, linux.IOSQE_IO_HARDLINK }) |flag| {
        rows[used] = try boundary(flag);
        used += 1;
    }
    if (used != rows.len) return error.RowCountWrong;
    var bytes: [4096]u8 = undefined;
    var output = std.Io.File.stdout().writerStreaming(init.io, &bytes);
    try std.json.Stringify.value(rows, .{ .emit_strings_as_arrays = true }, &output.interface);
    try output.interface.writeByte('\n');
    try output.interface.flush();
}

