import json
import subprocess
from pathlib import Path

OUT = Path(__file__).resolve().parent


def read_json(path):
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError) as error:
        raise RuntimeError("InvalidOwnedFlagJson") from error


def cqe(tag, result):
    return {"user_data": tag, "res": result, "flags": 0}


def stage(buffer=None, readable=None, witness=None):
    return {"buffer": [165, 165] if buffer is None else buffer,
            "b_readable": readable, "witness": witness}


def expected(plan):
    flag = plan["request_flags"]
    row = {"kind": plan["kind"], "request_flags": flag,
           "prepared_flags": [flag, 0, None], "submitted": [2, None],
           "early": [False, False, False],
           "completions": [cqe(i + 1, result) for i, result in enumerate(plan["results"])],
           "before": stage(), "after": stage(), "guards": 0}
    if len(row["completions"]) == 2:
        row["completions"].append(None)
    if plan["kind"] == "drain":
        ready = plan["prior_ready"]
        row.update(mode="blocked_drain" if ready else "blocked_prior",
                   prepared_flags=[0, flag, 0], submitted=[3, None],
                   early=plan["early"], guards=2,
                   before=stage([97, 165] if ready else [165, 165 if flag else 98],
                                plan["before_b_readable"], plan["before_witness"]),
                   after=stage([97, 98], False, 99 if flag else None))
    elif plan["kind"] == "link":
        row.update(mode=plan["mode"],
                   after=stage([97, 165] if plan["mode"] == "short" else [165, 165],
                               witness=plan["witness"]))
        if plan["mode"] == "invalid_opcode" and flag == 0:
            row["submitted"] = [1, 1]
    else:
        row.update(mode="split", submitted=plan["submissions"], early=plan["early"],
                   before=stage(witness=plan["before_witness"]),
                   after=stage([97, 165]), guards=1)
    return row


spec = read_json(OUT / "spec-current.json")
model = [expected(plan) for plan in spec["plans"]]
initial = read_json(OUT / "nineteen-plan.stdout")
if initial != model:
    raise RuntimeError(("InitialFlagModelMismatch", initial, model))
observations = []
for run in range(20):
    result = subprocess.run([str(OUT / "flag-probe")], capture_output=True,
                            text=True, timeout=15, check=False)
    (OUT / f"run-{run:02d}.stdout").write_text(result.stdout)
    (OUT / f"run-{run:02d}.stderr").write_text(result.stderr)
    if (result.returncode, result.stderr) != (0, ""):
        raise RuntimeError(("OwnedFlagProbeFailed", run, result.returncode, result.stderr))
    try:
        actual = json.loads(result.stdout)
    except ValueError as error:
        raise RuntimeError("InvalidOwnedFlagProbeOutput") from error
    if actual != model:
        raise RuntimeError(("FlagModelMismatch", run, actual, model))
    observations.append({"run": run, "plans": len(actual), "cqes": 42,
                         "guard_timeouts": 11, "submissions": 23})
(OUT / "model.json").write_text(json.dumps(model, indent=2) + "\n")
(OUT / "runs.json").write_text(json.dumps(observations, indent=2) + "\n")
print("20 processes;19 finite plans each;840 exact CQEs;460 submissions;220 guards;whole rows match scoped model;initial badFD classification retained.")
